INSERT INTO public.appointments (id, patient_id, schedule_id, status, cancel_reason, created_at, conclusion) OVERRIDING SYSTEM VALUE VALUES (5, 8, 4497, 'completed', NULL, '2026-09-27 09:00:00+03', 'Плановый осмотр, планирование беременности. Жалоб нет. Взят мазок на цитологию, результат будет готов через 5–7 дней. Рекомендован приём фолиевой кислоты и обследование перед планированием беременности.');
