INSERT INTO public.appointments (id, patient_id, schedule_id, status, cancel_reason, created_at, conclusion) OVERRIDING SYSTEM VALUE VALUES (7, 23, 5430, 'completed', NULL, '2026-09-29 11:30:00+03', 'Плановый осмотр. Жалоб нет. УЗИ органов малого таза без патологии. Повторный осмотр через год.');
INSERT INTO public.appointments (id, patient_id, schedule_id, status, cancel_reason, created_at, conclusion) OVERRIDING SYSTEM VALUE VALUES (8, 26, 5123, 'completed', NULL, '2026-10-05 10:00:00+03', 'Жалобы на быструю утомляемость. Патологии со стороны органов малого таза не выявлено. Рекомендован витамин D3, контроль уровня витамина D через 2 месяца.');
