INSERT INTO public.appointments (id, patient_id, schedule_id, status, cancel_reason, created_at, conclusion) OVERRIDING SYSTEM VALUE VALUES (23, 28, 1994, 'completed', NULL, '2026-10-05 09:20:00+03', 'ОРВИ (J06.9), период выздоровления. Температуры нет 3 дня, остаточный насморк. Рекомендовано промывание носа солевым раствором. Может посещать школу, освобождение от физкультуры на 1 неделю.');
