INSERT INTO public.appointments (id, patient_id, schedule_id, status, cancel_reason, created_at, conclusion) OVERRIDING SYSTEM VALUE VALUES (51, 14, 6451, 'completed', NULL, '2026-10-14 10:00:00+03', 'Профилактический осмотр. Жалоб нет. УЗИ почек и мочевого пузыря без патологии.');
INSERT INTO public.appointments (id, patient_id, schedule_id, status, cancel_reason, created_at, conclusion) OVERRIDING SYSTEM VALUE VALUES (52, 3, 5880, 'completed', NULL, '2026-10-06 12:30:00+03', 'Мочекаменная болезнь (N20.0). Жалобы на дискомфорт в поясничной области. УЗИ почек: конкременты до 3 мм в правой почке. Общий анализ мочи без патологии. Назначен Канефрон Н, питьё не менее 2 л в день. Контроль УЗИ через 3 месяца.');
